Case 1: Declarative Background Service
Save as desk_service_unit.nix. A complete NixOS service configuration.
# desk_service_unit.nix
{ pkgs, ... }:

{
  systemd.services.desk-worker = {
    description = "Desk Operations Background Processing Worker";
    wantedBy = [ "multi-user.target" ];
    after = [ "network-online.target" ];
    wants = [ "network-online.target" ];

    environment = {
      DESK_ENVIRONMENT = "production";
      PORT = "8080";
    };

    serviceConfig = {
      Type = "simple";
      ExecStart = "${pkgs.writeShellScript "worker" ''
        echo "Desk worker started on port $PORT"
        while true; do sleep 3600; done
      ''}";
      Restart = "on-failure";
      RestartSec = "5s";

      # Security Hardening
      DynamicUser = true;
      ProtectSystem = "strict";
      ProtectHome = true;
      NoNewPrivileges = true;
      PrivateTmp = true;
    };
  };
}
Notice: - DynamicUser = true; automatically allocates a temporary unprivileged system UID/GID without needing manual useradd commands. - ProtectSystem = "strict"; mounts the entire filesystem read-only for this process.


